import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name (case-insensitive).',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search string matched against product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate query
  if (typeof args.query !== 'string') {
    throw new Error('query must be a string');
  }

  // Validate limit if provided
  let limit;
  if (args.limit !== undefined) {
    if (!Number.isInteger(args.limit)) {
      throw new Error('limit must be an integer');
    }
    if (args.limit < 1 || args.limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    limit = args.limit;
  } else {
    limit = products.length;
  }

  // Reject unknown arguments
  const knownKeys = new Set(['query', 'limit']);
  for (const key of Object.keys(args)) {
    if (!knownKeys.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const q = args.query.toLowerCase();
  const results = products
    .filter(p => p.name.toLowerCase().includes(q))
    .slice(0, limit);

  const text = results.map(p => `${p.id}: ${p.name}`).join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}
